"""
Pydantic schemas for the per-case chat API.

The chat thread is a context-aware conversation anchored to a specific
repair case.  The system prompt includes the full structured_result from
the latest complete analysis, so the model already knows the problem type,
tools, steps, and severity — the user never has to re-explain anything.

Message roles mirror the standard chat convention:
  "user"      — a message typed by the human
  "assistant" — a reply generated by the AI model
"""

import datetime
from typing import Optional

from pydantic import BaseModel, ConfigDict


class MessageRequest(BaseModel):
    """Body for POST /cases/{case_id}/chat."""

    content: str
    image_ids: list[int] = []   # optional follow-up photo IDs uploaded via chat toolbar


class MessageResponse(BaseModel):
    """One message in the thread, returned by GET and POST."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    role: str           # "user" | "assistant"
    content: str
    created_at: datetime.datetime
